use mdbook_language_lab::process;
use serde_json::Value;
use std::io;
type Result<T> = std::result::Result<T, String>;

fn run() -> Result<()> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if !args.is_empty() {
        if args == ["supports", "html"] {
            return Ok(());
        }
        return Err("usage: mdbook-language-lab [supports html]".into());
    }
    let input: Value = serde_json::from_reader(io::stdin()).map_err(|e| e.to_string())?;
    let pair = input
        .as_array()
        .filter(|p| p.len() == 2)
        .ok_or("expected [context, book]")?;
    if pair[0]["renderer"] != "html" {
        return Err("only the html renderer is supported".into());
    }
    let mut book = pair[1].clone();
    process(&mut book)?;
    serde_json::to_writer(io::stdout(), &book).map_err(|e| e.to_string())
}

fn main() {
    if let Err(error) = run() {
        eprintln!("mdbook-language-lab: {error}");
        std::process::exit(1);
    }
}

pub fn process(book: &mut Value) -> Result<()> {
    // mdBook 0.4 used sections; 0.5 uses items. Preserve the input envelope.
    let key = if book.get("items").is_some() {
        "items"
    } else {
        "sections"
    };
    let items = book.get_mut(key).ok_or("missing book items")?;

use serde_json::{Value, json};
use std::io::Write;
use std::process::{Command, Stdio};

fn execute(input: &Value) -> std::process::Output {
    let mut child = Command::new(env!("CARGO_BIN_EXE_mdbook-language-lab"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(input.to_string().as_bytes())
        .unwrap();
    child.wait_with_output().unwrap()
}

#[test]
fn protocol_is_json_only_and_preserves_metadata() {
    let input = json!([{ "renderer": "html" }, {"items":[{"Chapter":{
        "path":"test.md", "content":"{req}`test.identity` Unique.", "sub_items":[]
    }}], "metadata": {"preserve":true}}]);
    let output = execute(&input);
    assert!(output.status.success());
    assert!(output.stderr.is_empty());
    let book: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(book["metadata"], input[1]["metadata"]);
    assert!(
        book["items"][0]["Chapter"]["content"]
            .as_str()
            .unwrap()
            .contains("requirement-badge")
    );
}
